import{_,W as e,X as o,Y as t}from"./framework-715d567f.js";const s={},n=t("p",null,"我用手机看盘，每天市场需要看的票不超过10个，都加自选，周期高度放第一，通过他还有其他个股的反馈判断周期出于什么阶段，同时观察下大盘的量能，最近盘前我会把30，20，10的涨停放在一个池里观察溢价情况，像今天的创板接力是负溢价，那1进2就会考虑谨慎介入，周五我也提了创业板溢价下降的问题，其实就是在正确的时间做正确的事，不逆势，不难的",-1),l=t("p",null,"多考虑高位情绪的整体性，高位哪些是要进监管，正在监管，进过了监管。",-1),c=t("p",null,"强势股要日成交额在7 8亿上，才算是市场合力",-1),d=t("p",null,"所以在考虑接力的同时要考虑到市场高位的情绪如何，要考虑获利盘释放的如何，在市场混沌甚至退潮阶段要考虑获利盘的充分释放，在市场情绪主升阶段要考虑高度的分歧低吸，不同的阶段干不同的事，量能这个东西我一直很看重，只有分歧-一致-分歧-一致才是龙头的良性走法，所以你可以看到很多龙头后期都是分歧-一致-一致-一致-天地板，那就是获利盘没有充分释放，一旦分歧获利盘倾泻而出造成的，有兴趣可以看看去年我回看大众，华强的帖子，这些结论都脱胎于这些极端行情中走出来的高度总结",-1),i=t("p",null,"最近是因为高位不补跌，所以才需要无脑高位，每天的复盘也都有在提，市场高度的示范效应，根据市场高度的反馈决定做高还是做低，是常规操作",-1),u=t("p",null,"首先看竞价整体表现，二是看高标反馈，三是看个股表现",-1),h=t("p",null,"分时高度，带量突破",-1),p=t("p",null,"也可以看看昨日均线高度",-1),r=[n,l,c,d,i,u,h,p];function a(f,m){return e(),o("div",null,r)}const B=_(s,[["render",a],["__file","M2358.html.vue"]]);export{B as default};
